-- ══════════════════════════════════════════════════════════════
-- DELTA EXECUTOR COMPATIBILITY SHIM
-- ══════════════════════════════════════════════════════════════
-- UI script runs BEFORE the main hub, so it needs its own fallbacks
-- for executor-specific globals. Without this, Delta users get errors
-- on buttons that copy text to clipboard, etc.
pcall(function()
    -- setclipboard: Delta has it but some forks use toclipboard
    if not setclipboard then
        if toclipboard then setclipboard = toclipboard
        elseif Clipboard and Clipboard.set then setclipboard = function(s) Clipboard:set(s) end
        else setclipboard = function() end end
        pcall(function() getgenv().setclipboard = setclipboard end)
        pcall(function() _G.setclipboard = setclipboard end)
    end
    -- identifyexecutor: Delta has it on newer builds
    if not identifyexecutor then
        identifyexecutor = function() return "Unknown", "0.0.0" end
        pcall(function() getgenv().identifyexecutor = identifyexecutor end)
    end
    -- gethui: fallback to CoreGui if missing
    if not gethui then
        gethui = function() return game:GetService("CoreGui") end
        pcall(function() getgenv().gethui = gethui end)
    end
    -- request alias for Server Hop / HTTP buttons
    if not request then
        if syn and syn.request then request = syn.request
        elseif http and http.request then request = http.request
        elseif http_request then request = http_request end
        pcall(function() if request then getgenv().request = request end end)
    end
end)

-- ══════════════════════════════════════════════════════════════
-- JNKIE SDK (Official Library — as per docs.jnkie.com)
-- Fault-tolerant load: works raw AND when re-wrapped by Jnkie protector
-- (Jnkie's own loader auto-injects the SDK; calling loadstring again
-- fails inside their sandbox → "attempt to call a nil value" at line 1)
-- ══════════════════════════════════════════════════════════════
local Junkie = nil

-- Try (1): SDK was already loaded by Jnkie's protector (preferred path)
if getgenv().Junkie and type(getgenv().Junkie) == "table" then
    Junkie = getgenv().Junkie
end

-- Try (2): Fetch the official SDK ourselves (raw run path)
if not Junkie then
    pcall(function()
        local src = game:HttpGet("https://jnkie.com/sdk/library.lua")
        if src and #src > 50 then
            local fn = loadstring(src)
            if fn then Junkie = fn() end
        end
    end)
end

-- Try (3): Stub fallback so the rest of the script never crashes
if not Junkie or type(Junkie) ~= "table" then
    Junkie = {
        service    = "",
        identifier = "",
        provider   = "Mixed",
        check_key  = function(key) return false, "Jnkie SDK unavailable - try re-running" end,
        get_link   = function() return "https://getsnowy.xyz/pricing" end,
    }
    warn("[SnowyHub] Jnkie SDK unavailable, using stub. Key validation may not work.")
end

-- Cache globally so re-runs reuse the same instance
getgenv().Junkie = Junkie

