    if input.KeyCode == Enum.KeyCode.V and UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) then
        if keyInput:IsFocused() then
            stopTips()
            tween(inputStroke, {Color = T.Success, Transparency = 0}, 0.1)
            tween(inputBg, {BackgroundColor3 = Color3.fromRGB(10, 35, 20)}, 0.1)
            task.wait(0.4)
            tween(inputStroke, {Color = T.Accent1, Transparency = 0.1}, 0.2)
            tween(inputBg, {BackgroundColor3 = T.BgGlass}, 0.2)
        end
    end
end)


-- ══════════════════════════════════════════════════════════
-- KEY TYPE DETECTION (visual badge only)
-- ══════════════════════════════════════════════════════════
local FREE_KEY_PREFIX = "SNOWY-FREE-"

local function detectKeyType(text)
    if #text == 0 then return "none" end
    if text:upper():sub(1, #FREE_KEY_PREFIX) == FREE_KEY_PREFIX:upper() then
        return "free"
    end
    return "premium"
end

