-- Close buttons
local function closeUI()
    if getgenv().UI_CLOSING then return end
    getgenv().UI_CLOSING = true
    -- Immediately remove blur so game doesn't stay blurry
    pcall(function() blurEffect.Size = 0 end)
    pcall(function() blurEffect:Destroy() end)
    blurEffect = nil
    -- Animate out
    tween(mainFrame, {Position = UDim2.new(0.5, -267.5, 0.6, -250)}, 0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
    tween(bgOverlay, {BackgroundTransparency = 1}, 0.3)
    task.wait(0.35)
    if Screen then Screen:Destroy() end
    getgenv().UI_CLOSED = true
end
leftClose.MouseButton1Click:Connect(closeUI)


-- Redeem Key → Junkie.check_key()
local isValidating = false
redeemBtn.MouseButton1Click:Connect(function()
    if isValidating then return end
    local key = keyInput.Text:gsub("%s+", "")
    local normalizedKey = key:upper()

    if key == "" then
        statusMsg.Text = "⚠ Please enter a key first"
        tween(statusMsg, {TextColor3 = T.Error}, 0.2)
        local orig = inputBg.Position
        for j = 1, 4 do
            tween(inputBg, {Position = UDim2.new(orig.X.Scale, orig.X.Offset + 8, orig.Y.Scale, orig.Y.Offset)}, 0.04)
            task.wait(0.04)
            tween(inputBg, {Position = UDim2.new(orig.X.Scale, orig.X.Offset - 8, orig.Y.Scale, orig.Y.Offset)}, 0.04)
            task.wait(0.04)
        end
        tween(inputBg, {Position = orig}, 0.08)
        return
    end

    isValidating = true
    statusMsg.Text = "⏳ Validating key..."
    tween(statusMsg, {TextColor3 = T.Warning}, 0.2)

    for _, d in pairs(redeemBtn:GetDescendants()) do
        if d:IsA("TextLabel") then d.Text = "⏳ Checking..." end
    end

    task.spawn(function()
        local isValid = false
        local tier = "none"
        local errMsg = "Invalid Key"

        -- ── FREE-SERVICE VALIDATION ───────────────────────────────
        -- Validate against the single free service (19097).
        -- ────────────────────────────────────────────────────────────
        configureService()
        local okCheck, checkResult = pcall(function() return Junkie.check_key(key) end)

        if okCheck and type(checkResult) == "table" and checkResult.valid then
            isValid = true
            tier    = "free"
        end

        if not isValid then
            if type(checkResult) == "table" then
                errMsg = checkResult.error or checkResult.message or errMsg
            elseif type(checkResult) == "string" then
                errMsg = checkResult
            end

            -- Normalize backend messages for the UI
            if errMsg == "KEY_INVALID" then
                errMsg = "Invalid Key"
            elseif errMsg == "KEY_EXPIRED" then
                errMsg = "Key expired — get a new one"
            elseif errMsg == "HWID_BANNED" then
                errMsg = "Hardware banned"
            elseif errMsg == "ALREADY_USED" then
                errMsg = "One-time key already used"
            elseif errMsg == "HWID_MISMATCH" then
                errMsg = "HWID limit reached"
            elseif errMsg == "SERVICE_NOT_FOUND" then
                errMsg = "Service not found — check Jnkie config"
            elseif errMsg == "SERVICE_MISMATCH" then
                errMsg = "Key is for a different service"
            elseif errMsg == "PREMIUM_REQUIRED" then
                errMsg = "Premium key required"
            end
        end

        local tierColor = T.Success
        local overlayBg = Color3.fromRGB(4, 20, 10)
        local flashColor = Color3.fromRGB(0, 200, 100)
        local overlayGrad1 = Color3.fromRGB(0, 35, 20)
        local overlayGrad2 = Color3.fromRGB(0, 20, 8)
        local tierLabel = "FREE ACCESS"
        local tierSub = "🎁  Free Tier — Limited Features"
        local tierIcon = "🎁"

        if tier == "free" then
            getgenv().KEY_TIER = "free"
            getgenv().JD_IS_PREMIUM = false
        elseif tier == "premium" then
            getgenv().KEY_TIER = "premium"
            getgenv().JD_IS_PREMIUM = true
            tierColor = T.Accent1
            overlayBg  = Color3.fromRGB(6, 10, 22)
            flashColor = T.Neon
            overlayGrad1 = Color3.fromRGB(15, 30, 60)
            overlayGrad2 = Color3.fromRGB(8, 15, 30)
            tierLabel  = "PREMIUM ACCESS"
            tierSub    = "⭐  Premium Tier — All unlocked"
            tierIcon   = "👑"
            local gold = Color3.fromRGB(220, 170, 30)
            tween(centerStroke, {Color = gold}, 0.2)
        end

        if isValid then
            -- Success Flow
            statusMsg.Text = "✨ Key authenticated!"
            tween(statusMsg, {TextColor3 = tierColor}, 0.2)
            
            for _, d in pairs(redeemBtn:GetDescendants()) do
                if d:IsA("TextLabel") then d.Text = "✓ Success" end
            end
            tween(inputStroke, {Color = tierColor, Thickness = 2}, 0.2)
            
            local overlay = Instance.new("Frame")
            overlay.Size = UDim2.new(1, 0, 1, 0)
            overlay.BackgroundColor3 = overlayBg
            overlay.BackgroundTransparency = 1
            overlay.BorderSizePixel = 0
            overlay.ZIndex = 50
            overlay.Parent = centerPanel
            corner(overlay, 18)
            gradient(overlay, overlayGrad1, overlayGrad2, 110)
            
            local checkIcon = Instance.new("TextLabel")
            checkIcon.Size = UDim2.new(0, 80, 0, 80)
            checkIcon.Position = UDim2.new(0.5, -40, 0.45, -40)
            checkIcon.BackgroundTransparency = 1
            checkIcon.Text = tierIcon
            checkIcon.TextColor3 = tierColor
            checkIcon.TextSize = 10
            checkIcon.Font = Enum.Font.GothamBlack
            checkIcon.ZIndex = 52
            checkIcon.Parent = overlay
            
            local ring = Instance.new("UIStroke")
            ring.Color = tierColor
            ring.Thickness = 4
            ring.Transparency = 1
            ring.Parent = checkIcon
            corner(checkIcon, 40)
            
            local sTxt = Instance.new("TextLabel")
            sTxt.Size = UDim2.new(1, 0, 0, 30)
            sTxt.Position = UDim2.new(0, 0, 0.45, 60)
            sTxt.BackgroundTransparency = 1
            sTxt.Text = tierLabel
            sTxt.TextTransparency = 1
            sTxt.TextColor3 = T.White
            sTxt.TextSize = 22
            sTxt.Font = Enum.Font.GothamBlack
            sTxt.ZIndex = 52
            sTxt.Parent = overlay
            
            local dTxt = Instance.new("TextLabel")
            dTxt.Size = UDim2.new(1, 0, 0, 20)
            dTxt.Position = UDim2.new(0, 0, 0.45, 95)
            dTxt.BackgroundTransparency = 1
            dTxt.Text = tierSub
            dTxt.TextTransparency = 1
            dTxt.TextColor3 = T.Grey
            dTxt.TextSize = 14
            dTxt.Font = Enum.Font.GothamMedium
            dTxt.ZIndex = 52
            dTxt.Parent = overlay
            
            local flash = Instance.new("Frame")
            flash.Size = UDim2.new(1, 0, 1, 0)
            flash.BackgroundColor3 = flashColor
            flash.BackgroundTransparency = 1
            flash.BorderSizePixel = 0
            flash.ZIndex = 60
            flash.Parent = centerPanel
            corner(flash, 18)
            tween(flash, {BackgroundTransparency = 0.5}, 0.1)
            task.wait(0.12)
            tween(flash, {BackgroundTransparency = 1}, 0.3)
            task.delay(0.5, function() flash:Destroy() end)
            
            tween(overlay, {BackgroundTransparency = 0.15}, 0.25)
            tween(checkIcon, {TextSize = 75}, 0.4, Enum.EasingStyle.Elastic)
            tween(ring, {Transparency = 0}, 0.2)
            task.wait(0.15)
            tween(sTxt, {TextTransparency = 0, Position = UDim2.new(0, 0, 0.45, 50)}, 0.25, Enum.EasingStyle.Back)
            tween(dTxt, {TextTransparency = 0, Position = UDim2.new(0, 0, 0.45, 80)}, 0.25, Enum.EasingStyle.Back)

            -- ─── PERF FIX: cut cosmetic delay 2s -> 0.4s ────────────
            -- Total post-validate delay was ~1.95s of pure cosmetic waits
            -- on top of the 3-5s hub compile freeze. Cut to 0.4s so the
            -- user gets to the loading overlay (and hub) much faster.
            task.wait(0.4)

            -- NUCLEAR KEY SET: Broadcast to all levels of memory
            local function broadcast(k, v)
                getgenv()[k] = v
                _G[k] = v
                shared[k] = v
            end

            -- ─── PERF FIX: Kill per-frame animation loop + blur BEFORE loading the hub ───
            -- The master Heartbeat runs at 60Hz touching ~12 UI instances; leaving it
            -- alive while the 18k-line hub synchronously builds its UI freezes the game
            -- to 0 FPS. Destroy all heavy UI *before* broadcasting SCRIPT_KEY (which
            -- releases the outer `while not SCRIPT_KEY` loop and triggers hub load).
            pcall(function() if masterConn then masterConn:Disconnect(); masterConn = nil end end)
            pcall(function() if blurEffect then blurEffect.Size = 0; blurEffect:Destroy(); blurEffect = nil end end)
            pcall(function() if Screen and Screen.Parent then Screen:Destroy() end end)
            getgenv().UI_CLOSING = true
            getgenv().UI_CLOSED  = true

            -- ─── PERF FIX: Persistent "Loading Hub..." overlay ────────
            -- The hub script is ~700KB and takes 3-5s to HttpGet + loadstring
            -- + synchronously build its UI. Without this overlay the user
            -- sees a frozen black screen for that entire window. We park a
            -- minimal lightweight ScreenGui in CoreGui that survives the
            -- UI destroy, and the hub script destroys it via
            -- getgenv().__SnowyLoadingOverlay:Destroy() when its UI is ready.
            -- A 60s safety timeout removes it if the hub never signals.
            local loadingOk, loadingScreen = pcall(function()
                local cg = (gethui and gethui()) or game:GetService("CoreGui")
                local sg = Instance.new("ScreenGui")
                sg.Name = "SnowyHubLoading"
                sg.IgnoreGuiInset = true
                sg.ResetOnSpawn = false
                sg.DisplayOrder = 999
                sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
                pcall(function() sg.Parent = cg end)
                if not sg.Parent then sg.Parent = game:GetService("CoreGui") end

                local bg = Instance.new("Frame")
                bg.Size = UDim2.new(1, 0, 1, 0)
                bg.BackgroundColor3 = Color3.fromRGB(8, 10, 18)
                bg.BackgroundTransparency = 0.15
                bg.BorderSizePixel = 0
                bg.Parent = sg

                local card = Instance.new("Frame")
                card.Size = UDim2.new(0, 360, 0, 140)
                card.Position = UDim2.new(0.5, -180, 0.5, -70)
                card.BackgroundColor3 = Color3.fromRGB(15, 18, 30)
                card.BorderSizePixel = 0
                card.Parent = bg
                local cardCorner = Instance.new("UICorner"); cardCorner.CornerRadius = UDim.new(0, 14); cardCorner.Parent = card
                local cardStroke = Instance.new("UIStroke"); cardStroke.Color = tierColor; cardStroke.Thickness = 1.5; cardStroke.Parent = card

                local title = Instance.new("TextLabel")
                title.BackgroundTransparency = 1
                title.Size = UDim2.new(1, -20, 0, 28)
                title.Position = UDim2.new(0, 10, 0, 16)
                title.Font = Enum.Font.GothamBold
                title.TextSize = 18
                title.TextColor3 = Color3.fromRGB(235, 240, 255)
                title.Text = "Loading Snowy Hub..."
                title.Parent = card

                local sub = Instance.new("TextLabel")
                sub.BackgroundTransparency = 1
                sub.Size = UDim2.new(1, -20, 0, 18)
                sub.Position = UDim2.new(0, 10, 0, 46)
                sub.Font = Enum.Font.GothamMedium
                sub.TextSize = 13
                sub.TextColor3 = Color3.fromRGB(160, 168, 190)
                sub.Text = "Compiling hub source • this may take a few seconds"
                sub.Parent = card

                local barBg = Instance.new("Frame")
                barBg.Size = UDim2.new(1, -40, 0, 6)
                barBg.Position = UDim2.new(0, 20, 1, -34)
                barBg.BackgroundColor3 = Color3.fromRGB(28, 32, 48)
                barBg.BorderSizePixel = 0
                barBg.Parent = card
                local barCorner = Instance.new("UICorner"); barCorner.CornerRadius = UDim.new(1, 0); barCorner.Parent = barBg

                -- ─── STATIC loading bar (no tween animation) ──────
                -- Filled bar with a diagonal gradient + bright accent dots
                -- gives the impression of progress without any motion.
                local bar = Instance.new("Frame")
                bar.Size = UDim2.new(1, 0, 1, 0)
                bar.BackgroundColor3 = tierColor
                bar.BorderSizePixel = 0
                bar.Parent = barBg
                local bCorner = Instance.new("UICorner"); bCorner.CornerRadius = UDim.new(1, 0); bCorner.Parent = bar

                -- Diagonal gradient stripe for a "loading" feel without motion
                local barGrad = Instance.new("UIGradient")
                barGrad.Color = ColorSequence.new({
                    ColorSequenceKeypoint.new(0.0, tierColor),
                    ColorSequenceKeypoint.new(0.5, Color3.new(
                        math.min(1, tierColor.R + 0.25),
                        math.min(1, tierColor.G + 0.25),
                        math.min(1, tierColor.B + 0.25))),
                    ColorSequenceKeypoint.new(1.0, tierColor),
                })
                barGrad.Transparency = NumberSequence.new({
                    NumberSequenceKeypoint.new(0.0, 0.0),
                    NumberSequenceKeypoint.new(0.5, 0.3),
                    NumberSequenceKeypoint.new(1.0, 0.0),
                })
                barGrad.Rotation = 35
                barGrad.Parent = bar

                return sg
            end)

            if loadingOk and loadingScreen then
                getgenv().__SnowyLoadingOverlay = loadingScreen
                -- Safety fallback: auto-destroy after 60s in case hub never signals ready
                task.delay(60, function()
                    pcall(function()
                        if getgenv().__SnowyLoadingOverlay == loadingScreen then
                            loadingScreen:Destroy()
                            getgenv().__SnowyLoadingOverlay = nil
                        end
                    end)
                end)
            end

            -- Yield a frame so the destroy + overlay creation commits before heavy work begins
            task.wait()

            -- ── Handoff to main hub ──────────────────────────────
            -- Both UI and main hub validate against the SAME free service
            -- (19097). Pass the REAL key so the main hub wrapper re-validates
            -- it successfully. Premium gating is enforced in orginalsrchub.txt.
            -- ─────────────────────────────────────────────────────
            broadcast("SCRIPT_KEY",     key)
            broadcast("KEY_TIER",       tier)
            broadcast("JD_IS_PREMIUM",  tier == "premium")

            configureService()

        else
            statusMsg.Text = "❌ " .. errMsg
            tween(statusMsg, {TextColor3 = T.Error}, 0.2)
            tween(inputStroke, {Color = T.Error, Thickness = 2}, 0.15)

            for _, d in pairs(redeemBtn:GetDescendants()) do
                if d:IsA("TextLabel") then d.Text = "✓ Redeem" end
            end

            local orig = inputBg.Position
            for j = 1, 4 do
                tween(inputBg, {Position = UDim2.new(orig.X.Scale, orig.X.Offset + 12, orig.Y.Scale, orig.Y.Offset)}, 0.04)
                task.wait(0.04)
                tween(inputBg, {Position = UDim2.new(orig.X.Scale, orig.X.Offset - 12, orig.Y.Scale, orig.Y.Offset)}, 0.04)
                task.wait(0.04)
            end
            tween(inputBg, {Position = orig}, 0.08)
            task.wait(1.5)
            tween(inputStroke, {Color = T.Border, Thickness = 1.5}, 0.3)
            if statusMsg.Text:find(errMsg) then
                statusMsg.Text = "🔑 Enter your key to access the script"
                tween(statusMsg, {TextColor3 = T.Grey}, 0.3)
            end
        end
        isValidating = false
    end)
end)

while not getgenv().SCRIPT_KEY and not getgenv().UI_CLOSED do
    task.wait(0.1)
end

